        if post_residual >= next_item_size {
            // Reward bins that can accommodate the next item (Best Fit lookahead).
            score -= (bin_capacity - post_residual) as f64 * 0.2;
        } else {
            // Penalize if this choice makes the next item impossible to place in this bin.
            score += 15.0;
        }
    }

    // Balance open bins: If many bins are open, push towards tighter packing.
    // Otherwise, be more lenient to prevent fragmentation.
    score += (open_bins_count as f64) * 0.5;

    // Threshold logic: If this is the last chance for the current bin, 
    // prioritize filling it if the post_residual is small (efficient).
    if fitting_bins_count == 1 && post_residual < 15 {
        score -= 20.0;
    }

    // If considering a new bin (bin_residual == bin_capacity), 
    // only choose it if it's the only option or if the current packing is extremely inefficient.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = 0.0;
        } else {
            // High penalty for opening a new bin if we have existing capacity.
            score = 60.0 + (mean_residual * 0.5);
        }
