        score += 50.0 + (10.0 - post_residual as f64) * 10.0;
    }

    // 2. If this is a new bin, apply a threshold penalty based on open_bins_count
    // This forces the algorithm to use existing bins unless they are very poor fits.
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64 * 0.5);
    }

    // 3. Lookahead adjustment: If the next item could fit into this post_residual,
    // we prioritize this bin (Best Fit behavior).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    // 4. If this is the last fitting bin, we are forced to use it. 
    // We heavily discount its score to prevent opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // 5. Global pressure: As the stream progresses, prioritize closing bins
    // by penalizing empty space more heavily when few items remain.
    let progress = step_index as f64 / total_items as f64;
    score += (progress * 10.0) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Prioritize Best-Fit: penalize large post_residuals to keep bins packed tightly.
    // 2. Lookahead mechanism: If the post_residual can perfectly or nearly accommodate the next item, 
    //    reward this bin heavily to create a "perfect pair".
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact fit or near-exact fit for the next item
            let fit_diff = (post_residual - next_item_size) as f64;
            score -= 150.0 / (fit_diff + 1.0);
        } else {
            // Penalize if this bin becomes unusable for the next item but others might be available
            score += 20.0;
        }
    }

    // 3. Prevent fragmentation: If we have many open bins, penalize creating a new one unless 
    //    it is a very high quality fit (Best-Fit logic).
    if bin_residual == bin_capacity {
        if open_bins_count > 0 {
            score += 45.0; // Heavy penalty for opening new bins if others exist
        }
    }

    // 4. Mean-residual balancing: If this bin's post_residual is significantly worse than 
    //    the global mean of open bins, penalize it to encourage leveling out.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // 5. Urgency factor: If this is the last chance for this item (fitting_bins_count == 1),
    //    don't let the "new bin" penalty prevent a valid placement.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Progress factor: As we approach the end of the stream, prioritize closing bins
    //    by rewarding lower post_residuals (aiming for full bins).
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // Strategy: Favor tight fits (Best-Fit principle) while penalizing fragmentation that kills potential for future items.

    let mut score = post_residual as f64;

