    // Heavily penalize tiny gaps unless it's a perfect fit.
    if post_residual > 0 && post_residual < 8 {
        score += 25.0;
    }

    // 2. Lookahead Coupling: If the next item is large, avoid leaving a residual that is slightly smaller than it.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // 3. Global State Awareness: If we are late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: decreases as we approach the end of the stream,
        // but remains high to encourage filling existing bins first.
        score += 45.0 * (1.0 - progress * 0.2);
    }

    // 4. Density Balancing: If the current bin's residual is significantly better than the global mean, 
    // it's a "good" bin. We want to keep it available for items that fit it tightly.
    if post_residual < mean_residual as u32 {
        score -= 5.0;
    }

    // 5. Urgency: If this is the only bin that fits the current item (fitting_bins_count == 1),
    // heavily bias toward picking it to avoid unnecessary new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // 6. Perfect fit reward
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
