    // by penalizing empty space more heavily.
    score += (progress * 20.0) * (post / bin_capacity as f64);

    // If this is the only bin that fits, we lower the score to force the selection
    // unless the gap created is extremely inefficient.
    if fitting_bins_count == 1 && post < 20.0 {
