        }
    }

    // 4. Harmonic Alignment: Favor bins that align with common modular denominators.
    // This helps in creating "classes" of bins (e.g., bins that hold 2 large items).
    let harmonic_fit = (post_residual % 25) as f64;
    score += harmonic_fit * 0.2;

    // 5. Progression scaling: As we approach the end of the stream, 
    // prioritize closing open bins over starting new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += progress * 100.0;
    }

    score
}

