    // Final adjustment: Penalize "almost full" bins if we have many bins open, 
    // to encourage consolidating items into fewer, fuller bins.
    if fitting_bins_count > 1 && post_res < 10.0 {
        score -= 5.0; 
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic: Harmonic-inspired Best-Fit with Lookahead Penalty (HBF-LP)
    // We aim to minimize the post_residual, but heavily penalize "orphaned" residuals 
    // that are too small to fit common future items (the "fragmentation threshold").

    let mut score = post_residual as f64;

    // 1. Penalize creating "dead zones" (residuals < 10) unless it's a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // 2. Harmonic Lookahead: If the next item cannot fit in this post_residual,
    // penalize the bin proportionally to how much wasted space is created.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // 3. Adaptive Threshold: If we are near the end of the stream, prioritize 
    // filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if fitting_bins_count == 0 {
        // This is a new bin candidate. 
        // Penalize opening a new bin early, but reduce penalty as we near the end.
        score += 30.0 * (1.0 - progress);
    } else {
        // If we have fitting bins, reward packing into bins that bring the 
        // residual closer to the mean_residual (balancing).
        let imbalance = (post_residual as f64 - mean_residual).abs();
        score -= imbalance * 0.2;
    }

    // 4. Harmonic Alignment: Reward residuals that are multiples of common item sizes (e.g., 20, 25).
    // This creates "cleaner" bins for future packing.
    if post_residual % 20 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: Heavily penalize small gaps that are unlikely to fit future items (e.g., < 10)
    if post_residual > 0 && post_residual < 10 {
