            let density_factor = (bin_capacity as f64 - mean_residual) / bin_capacity as f64;
            score += 55.0 * (1.0 + density_factor);
        }
    }

    // 4. Residual Variance Smoothing:
    // Penalize bins that deviate from the mean_residual to maintain uniform bin states.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.8;

    // 5. Critical Placement:
    // If we have very few fitting options, we lower the barrier for existing bins
    // to ensure we don't force a new bin unnecessarily.
    if fitting_bins_count > 0 && fitting_bins_count <= 2 {
        score -= 40.0;
    }

    // 6. Terminal Phase Aggression:
    // As we approach the end of the stream, increase the cost of leaving 
    // any residual space, forcing tighter, "crammed" packing to finish the stream.
    let progress = step_index as f64 / total_items as f64;
    score += progress * (post_residual as f64 * 0.75);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;

