        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // 3. Residual Variance Normalization:
    // Discourage outliers in bin fullness to maintain a uniform residual distribution.
    let dev = (post_residual as f64 - mean_residual).abs();
    if post_residual as f64 > mean_residual {
        score += dev * 0.4;
    } else {
        score -= dev * 0.2;
    }

    // 4. Scarcity Logic:
    // If we only have one option that fits, take it regardless of quality.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 100.0;
    }

    // 5. Tail-end compaction:
    // In the final 10% of items, heavily weight towards completing bins.
    if step_index > (total_items * 9 / 10) {
        score += post_residual as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
