    if (post_residual as f64) > target_residual {
        score += (post_residual as f64 - target_residual) * (2.1 + progress * 1.5);
    }

    // 4. Critical Path Constraint:
    // Prioritize bins that are 'versatile' (can fit the next item) when fitting_bins_count is low.
    if fitting_bins_count > 0 && !is_new_bin {
        let versatility_bonus = if post_residual >= next_item_size { 210.0 } else { 70.0 };
        score -= versatility_bonus * (1.0 - progress * 0.5);
    }

    // 5. Adaptive Compaction:
    // Aggressive late-stage penalty to force high-density packing.
    let late_stage_factor = (progress - 0.25).max(0.0) / 0.75;
    score += (post_residual as f64) * (0.5 + (late_stage_factor * 4.0));

    // 6. Entropy Mitigation:
    // Penalize mid-fill fragmentation that blocks large item placement.
    if fill_ratio > 0.4 && fill_ratio < 0.8 && !is_new_bin {
        score += 150.0 * (1.0 + progress);
    }

    // 7. Small Item Aggregation:
    // Encourage filling deep residuals with small items to prevent 'bin-bloat'.
    if item_size < (bin_capacity / 5) && !is_new_bin {
        score -= 110.0 * (1.0 - fill_ratio.powf(0.6));
    }

    // 8. Residual Parity:
    // Strong bias towards clearing residual space completely.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 2 {
        score -= 75.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
