    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // 1. Predictive Lookahead Optimization:
    // Enhanced slack sensitivity: prioritize bins that leave exactly enough space for next_item
    if next_item_size > 0 {
        if post_residual == 0 {
            score -= 420.0; 
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Stronger reward for "exact fit" probability on next step
            score -= 680.0 / (slack.powf(0.28) + 1.1);
        } else if !is_new_bin {
            score += 240.0 + (item_size as f64 * 1.35);
        }
    }

    // 2. Dynamic New-Bin Thresholding:
    if is_new_bin {
        // Stiffer resistance to new bins; scale by inverse of remaining item count to avoid late-game bloat
        let remaining_ratio = 1.0 - progress;
        let density_pressure = (open_bins_count as f64 / (total_items as f64 / 45.0)).min(16.0);
        score += 380.0 * (1.0 + density_pressure * progress.powf(0.6)) + (mean_residual * 2.8) + (remaining_ratio * 120.0);
    } else {
        // Reward filling bins to near-zero residuals with higher intensity for small items
        if post_residual < 22 {
            score -= (240.0 - (post_residual as f64 * 11.0));
        }
    }

    // 3. Residual Variance Control:
    // Tighter suppression of high-residual bins, especially early-mid stream
    let target_residual = mean_residual * (0.35 - (progress * 0.20));
    if (post_residual as f64) > target_residual {
        score += (post_residual as f64 - target_residual) * (3.2 + progress * 2.2);
    }

    // 4. Critical Path Constraint:
    // Favor bins that have "Goldilocks" space (not too empty, not too full)
    if fitting_bins_count > 0 && !is_new_bin && (bin_residual > (item_size * 2)) {
        score -= 290.0 * (1.0 - progress * 0.40);
    }

    // 5. Adaptive Compaction:
    // Aggressive penalty for slack, non-linear progression to force tight packing
    let late_stage_factor = (progress - 0.20).max(0.0) / 0.80;
    score += (post_residual as f64) * (0.95 + (late_stage_factor * 7.5));

    // 6. Entropy Mitigation:
    // Penalty for mid-range "dead zones" (35-80%)
    if fill_ratio > 0.35 && fill_ratio < 0.80 && !is_new_bin {
        score += 220.0 * (1.0 + progress * 1.25);
    }

    // 7. Small Item Aggregation:
    if item_size <= (bin_capacity / 9) && !is_new_bin {
        score -= 180.0 * (1.0 - fill_ratio.powf(0.40));
    }

    // 8. Residual Parity:
    // Final reward for near-perfection
    if post_residual == 0 {
        score -= 210.0;
    } else if post_residual <= 2 {
        score -= 135.0;
    }

    score
}

