    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best-Fit principle).
    let mut score = post_residual as f64;

    // Penalty for creating "fragmented" space (small, unusable residuals).
    // If post_residual is small but > 0, it's often a "dead zone".
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead: If the next item is large, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - progress);
        } else {
            score += 10.0 * progress;
        }
    }

    // Handling the "New Bin" decision threshold.
    if is_new_bin {
        // Only open a new bin if the current fit quality is generally poor.
        // As the stream progresses, we become more conservative about opening new bins.
        score += 45.0 + (20.0 * progress);

        // If there are many bins already open, penalize opening another one heavily.
        score += (open_bins_count as f64) * 5.0;
    } else {
        // Reward bins that bring the mean residual closer to a target density.
        // Aiming for tighter packing (lower mean_residual).
        let density_diff = (post_residual as f64 - mean_residual).abs();
        score += 0.5 * density_diff;
    }

    // If this is the only bin that can fit the item, prioritize it to avoid forced new bins.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let is_new_bin = bin_residual == bin_capacity;
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // 1. Predictive Lookahead Optimization:
    // Increased penalty for items that leave a "fragmentation hole" smaller than the next item.
    if next_item_size > 0 {
        if post_residual == 0 {
            score -= 385.0; 
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 640.0 / (slack.powf(0.30) + 1.1);
        } else if !is_new_bin {
            score += 230.0 + (item_size as f64 * 1.35);
        }
    }

    // 2. Dynamic New-Bin Thresholding:
    if is_new_bin {
        // Higher resistance to new bin creation; penalize opening new bins when current mean_residual is low.
        let density_pressure = (open_bins_count as f64 / (total_items as f64 / 55.0)).min(16.0);
        score += 345.0 * (1.0 + density_pressure * progress.powf(0.65)) + (mean_residual * 2.8);
    } else {
        // Reward filling bins to near-zero residuals with higher intensity.
        if post_residual < 20 {
            score -= (230.0 - (post_residual as f64 * 13.2));
        }
    }

    // 3. Residual Variance Control:
    // Tighter suppression of high-residual bins, especially as the stream progresses.
    let target_residual = mean_residual * (0.35 - (progress * 0.20));
    if (post_residual as f64) > target_residual {
        score += (post_residual as f64 - target_residual) * (3.2 + progress * 3.0);
    }

    // 4. Critical Path Constraint:
    // Protect bins with high potential for small follow-ups.
    if fitting_bins_count > 0 && !is_new_bin && (bin_residual > (item_size * 2)) {
        score -= 285.0 * (1.0 - progress * 0.30);
    }

    // 5. Adaptive Compaction:
    // Aggressive penalty for slack, scaled by remaining stream.
    let late_stage_factor = (progress - 0.25).max(0.0) / 0.75;
    score += (post_residual as f64) * (1.05 + (late_stage_factor * 7.5));

    // 6. Entropy Mitigation:
    // Narrower focus on "dead zones" (35-90%) to force tighter packing.
    if fill_ratio > 0.35 && fill_ratio < 0.90 && !is_new_bin {
        score += 220.0 * (1.0 + progress * 1.3);
    }

    // 7. Small Item Aggregation:
    // Force tiny items (<= 15% capacity) into existing bins to improve compaction.
    if item_size <= (bin_capacity * 15 / 100) && !is_new_bin {
        score -= 175.0 * (1.0 - fill_ratio.powf(0.40));
    }

    // 8. Residual Parity:
    // Reward finishing a bin (0) or nearly finishing it (1-3 units).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 3 {
        score -= 130.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

