    // that are unlikely to accommodate future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Coupling: If next_item_size fits in this post_residual, reward the placement.
    // This implements a primitive Best-Fit-Decreasing lookahead optimization.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
