    // 3. New Bin Thresholding: If this is an empty bin, add a "cost of opening" penalty.
    // This discourages opening new bins unless the current options are very poor.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    // 4. Harmonic Density Balancing: Encourage placing items in bins that bring the 
    // bin residual closer to the mean_residual, effectively grouping bins of similar fullness.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    // 5. Last Chance Logic: If this is the only bin that fits the current item, 
    // prioritize it to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 6. Progression Scaling: As the stream nears completion, become more aggressive 
    // about filling existing bins to minimize the total count.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

