    if is_new_bin {
        let density_pressure = (open_bins_count as f64 / (total_items as f64 / 60.0)).min(15.0);
        score += 330.0 * (1.0 + density_pressure * progress.powf(0.8)) + (mean_residual * 2.6);
    } else {
        // Reward filling bins to near-zero residuals for existing bins
        if post_residual < 20 {
            score -= (220.0 - (post_residual as f64 * 11.0));
        }
    }

    // Residual Variance Control:
    // Penalize high-residual bins more aggressively in late-stage packing.
    let target_residual = mean_residual * (0.45 - (progress * 0.3));
    if post > target_residual {
        score += (post - target_residual) * (3.0 + progress * 3.0);
    }

    // Critical Path: Prefer bins that have enough space to handle current item
    // and aren't "too full" to accept subsequent small items.
    if !is_new_bin && bin_residual > (item_size * 2) {
        score -= 280.0 * (1.0 - progress * 0.4);
    }

    // Adaptive Compaction:
    // Aggressive penalty for slack, growing linearly with progress.
    score += post * (0.9 + (progress * 7.0));

    // Entropy Mitigation:
    // Penalize mid-range "dead zones" (40-85% usage) to prevent fragmented bin state.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if fill_ratio > 0.4 && fill_ratio < 0.85 && !is_new_bin {
        score += 210.0 * (1.0 + progress * 1.2);
    }

    // Small Item Aggregation:
    // Force items <= 10% capacity into existing bins to minimize mean_residual.
    if item_size <= (bin_capacity / 10) && !is_new_bin {
        score -= 180.0 * (1.0 - fill_ratio.powf(0.5));
    }

    // Residual Parity:
    // Heavily reward perfect fits to drive compaction.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 2 {
        score -= 120.0;
    }

