    }

    // New Bin Heuristic:
    // If bin_residual == bin_capacity, we are considering a new bin.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin if an existing bin could fit it.
        // As the stream progresses, we want to maximize bin utilization.
        let new_bin_penalty = 65.0 + (progress * 25.0) + (fitting_bins_count as f64 * 12.0);
        score += new_bin_penalty;
    } else {
        // Existing bin logic:
        // Favor bins that push the residual closer to the global mean,
        // which helps maintain uniform packing density across all bins.
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.2;

        // Secondary Best Fit: Favor filling bins that are already near capacity
        // to minimize the number of "half-empty" bins.
        score += (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Edge case: If the bin is perfectly filled, provide a massive reward.
    if post == 0.0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
