    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating "slivers" (unusable space). 
    // Adjusted by remaining capacity to avoid stranding items.
    if post_residual > 0 && post_residual < 12 {
        score += 32.0 * (1.0 + progress);
    }

    // Lookahead refinement: Reward bins that accommodate the next item AND
    // leave a residual that is likely to be useful for the mean distribution.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 22.0;
            // Reward "perfect fit" potential for the next item
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // Penalty for stranding the next item, scaled by capacity pressure.
            score += 18.0 * (open_bins_count as f64 / (total_items - step_index) as f64).min(2.0);
        }
    }

    // Dynamic New Bin Logic:
    // If we are nearing the end of the stream, be more aggressive about opening
    // new bins to prevent late-game fragmentation.
    if is_new_bin {
        if fitting_bins_count > 0 {
            // Threshold-based penalty: only open new if current fit is significantly worse
            // than the average residual.
            score += 75.0 - (progress * 20.0);
        } else {
            score -= 12.0;
        }
    }

    // Balance against mean_residual using a non-linear curvature.
    // This helps homogenize bin fill levels across the packing set.
    let residual_diff = (post_residual as f64) - mean_residual;
    score += residual_diff.powi(2) * 0.05 * (if residual_diff > 0.0 { 1.0 } else { -0.5 });

    // Best Fit / Worst Fit pressure:
    // Favor bins that are already well-utilized to reduce open_bins_count.
    score += (bin_capacity - bin_residual) as f64 * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Penalize new bin creation heavily early on, but allow it if fitting is inefficient.
    // We aim for "Best Fit" behavior while incorporating lookahead and stream density.
    let mut score = post_residual as f64;

    // 1. Base Best-Fit Penalty: Square the residual to exponentially favor tighter fits.
    score = score.powi(2);

    // 2. Lookahead Coupling: If the next item is large, penalize small post_residuals 
    // that would strand the bin and force a new bin for the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 2.5;
        }
    }

    // 3. New Bin Thresholding: Dynamic bias against opening new bins.
    // As the stream progresses, we become more tolerant of opening new bins to optimize packing.
    if is_new_bin {
        // High base cost for new bin, modulated by progress and open bin count.
        let new_bin_cost = 2500.0 * (1.0 - (progress * 0.5)) + (open_bins_count as f64 * 10.0);
        score += new_bin_cost;
    } else {
        // 4. Density Balancing: If we have many bins, favor filling those with lower residuals
        // to consolidate space.
        let residual_deviation = (bin_residual as f64 - mean_residual).abs();
        score -= residual_deviation * 0.5;
    }

    // 5. Criticality: If this is the only bin that fits, prioritize it heavily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 500.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
