    let progress = step_index as f64 / total_items as f64;
    let tightness_factor = 1.0 + (progress * 2.0);

    // Fragment minimization: Heavily penalize near-zero residuals that are too small for any likely item.
    if post_residual > 0 && post_residual < 12 {
        score += 35.0 * tightness_factor;
    }

    // Lookahead optimization: Reward residuals that match next_item_size exactly (perfect fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if post_residual > next_item_size {
            score -= 12.0;
        } else {
