    // Dynamic new-bin gating: Only open a new bin if the current bin's residual 
    // is significantly worse than the expected mean.
    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 65.0 + (open_bins_count as f64 * 0.5);
        } else {
            score -= 10.0;
        }
    } else {
        // Best Fit logic: Encourage filling the most occupied bins first.
        score += (bin_capacity - bin_residual) as f64 * 0.25;

        // Variance control: Keep residuals close to the global mean to avoid outliers.
        let diff = (post_residual as f64 - mean_residual).abs();
        score += diff * 0.15;
    }

    // Threshold for "near-full" bins: If a bin can hold the next item and result in 
    // an extremely small residual, prioritize it to clear the bin.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

