    // As we approach the end of the stream, we become more tolerant of small fragments.
    let progress = step_index as f64 / total_items as f64;
    let fragmentation_threshold = 22.0 - (progress * 10.0);
    if post_residual > 0 && (post_residual as f64) < fragmentation_threshold {
        score += 32.0 * (1.0 - progress);
    }

    // 2. Lookahead Coupling: Reward alignment with next_item_size.
    // If we can fit the next item perfectly (post_residual == 0), give a massive bonus.
    if next_item_size > 0 {
        if post_residual == 0 {
            score -= 22.0;
        } else if post_residual >= next_item_size {
            score -= 18.0;
        } else {
