        }
    }

    // 3. Adaptive New Bin Control: Use the ratio of open bins to total items to decide threshold.
    // Prevents premature new bin opening early in the stream.
    if is_new_bin {
        let density_factor = (open_bins_count as f64) / (step_index + 1) as f64;
        if fitting_bins_count > 0 {
