        } else {
            score -= 8.0;
        }
    }

    // 4. Residual Variance Balancing:
    // Instead of simple mean, use a non-linear penalty for bins that deviate from the 
    // current packing average, but normalize by bin_capacity.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += (dev / bin_capacity as f64) * 15.0;

    // 5. Best-Fit Momentum:
    // Heavily weight towards filling bins to capacity to minimize variance in bin residuals.
    // Increased weight on (bin_capacity - bin_residual) to favor "Best Fit" behavior.
    score += (bin_capacity - bin_residual) as f64 * 0.25;

    // 6. Final adjustment for very small bins:
    // If the bin is nearly full (residual < item_size), prioritize finishing it.
    if post_residual < item_size && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit Penalty: Minimize post_residual (Best Fit principle)
    // The base score (post_residual) already favors tight packing.

    // 2. Lookahead Synergy (Harmonic/Modulo coupling)
    // If next_item_size fits in the post_residual, drastically reduce the score to encourage pairing.
    if next_item_size > 0 && next_item_size <= post_residual {
