    // If post_residual is small but not zero, it's often unusable ("dead space").
    // Penalize remainders between 1 and 9 (assuming most items > 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 4. Strategic New Bin Thresholding
    // If this is a new bin (bin_residual == bin_capacity):
    if bin_residual == bin_capacity {
        // Only open a new bin if we have many open bins already that are "cluttered".
        // If fitting_bins_count is low, we are forced to open a new one.
        if fitting_bins_count > 0 {
            // Heavily penalize opening a new bin if an existing bin could fit the item.
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // If no existing bin fits, it's a necessary placement.
            score -= 10.0;
        }
    }

    // 5. Global Efficiency Normalization
    // As we reach the end of the stream, prioritize closing existing bins.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
