    let is_new_bin = bin_residual == bin_capacity;
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    // 1. Predictive Lookahead Optimization:
    // Refined to prioritize the "exact match" and next-item fit more aggressively.
    if next_item_size > 0 {
