        }
    }

    // 2. Dynamic New-Bin Thresholding:
    if is_new_bin {
        let density_pressure = (open_bins_count as f64 / (total_items as f64 / 50.0)).min(15.0);
        // Increased resistance to opening new bins early to force tighter packing
        score += 380.0 * (1.0 + density_pressure * progress.powf(0.75)) + (mean_residual * 2.4);
    } else {
        // Reward filling bins to near-zero residuals more heavily
        if post_residual < 20 {
            score -= (220.0 - (post_residual as f64 * 10.5));
        }
    }

    // 3. Residual Variance Control:
    // Stricter suppression of high-residual bins.
    let target_residual = mean_residual * (0.42 - (progress * 0.25));
    if (post_residual as f64) > target_residual {
        score += (post_residual as f64 - target_residual) * (2.8 + progress * 2.5);
    }

    // 4. Critical Path Constraint:
    // Protect bins that can fit the current item and have high potential for follow-ups.
    if fitting_bins_count > 0 && !is_new_bin && (bin_residual > (item_size + next_item_size)) {
        score -= 280.0 * (1.0 - progress * 0.3);
    }

    // 5. Adaptive Compaction:
    // Penalty for slack scaled by remaining capacity; increased sensitivity to late-stage fragmentation.
    let late_stage_factor = (progress - 0.25).max(0.0) / 0.75;
    score += (post_residual as f64) * (0.75 + (late_stage_factor * 6.5));

    // 6. Entropy Mitigation:
    // Penalty for "dead zones" (40-85%) that hinder tight packing.
    if fill_ratio > 0.40 && fill_ratio < 0.85 && !is_new_bin {
        score += 200.0 * (1.0 + progress * 0.8);
    }

    // 7. Small Item Aggregation:
    // Force items (<= 12% capacity) into existing bins to maintain low mean_residual.
    if item_size <= (bin_capacity * 12 / 100) && !is_new_bin {
        score -= 150.0 * (1.0 - fill_ratio.powf(0.4));
    }

    // 8. Residual Parity:
    // Reward finishing a bin or nearly finishing it (tight fit).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 2 {
        score -= 120.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
