    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Predictive Lookahead: Optimized slack-matching
    if next_item_size > 0 {
        if post_residual == 0 {
            score -= 525.0; 
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 445.0 / (1.0 + slack.powf(0.75) * 0.12);
        } else if !is_new_bin {
            score += 540.0 * (1.0 - progress).powf(0.5) * (1.0 + (open_bins_count as f64 * 0.25));
        }
    }

    // 2. Adaptive New-Bin Thresholding: Aggressive consolidation
    if is_new_bin {
        let utilization = 1.0 - (mean_residual / bin_capacity as f64);
        score += 680.0 + (utilization * 920.0) + (progress * 520.0) + (open_bins_count as f64 * 7.5);
    } else if post_residual < (bin_capacity / 6) {
        score -= 610.0 * (1.0 - (post_residual as f64 / (bin_capacity as f64 / 6.0)).powi(2));
    }

    // 3. Residual Balancing: Tighter focus on target drift
    let residual_diff = post_residual as f64 - (mean_residual * 0.72);
    score += residual_diff.powi(2) * 0.48;

    // 4. Scarcity & Entropy: Prioritize existing bins
    if fitting_bins_count <= 3 && !is_new_bin {
        score -= 1050.0;
    }

    // 5. Temporal Compaction: Adaptive penalty refinement
    if progress > 0.92 {
        score += (post_residual as f64).powf(1.25) * 280.0;
    } else {
        score -= (post_residual as f64) * 14.2;
    }

    // 6. Sliver Mitigation: Optimized for the 2-28 range to prevent dead-end gaps
    if post_residual > 1 && post_residual <= 28 {
        score += 840.0 * (1.0 - (post_residual as f64 / 28.0)).powf(1.6);
    }

    // 7. Density Constraint: Target tighter residual clustering
    let target_residual = bin_capacity as f64 * 0.04;
    score += (post_residual as f64 - target_residual).abs() * 16.5;

    // 8. Small Item Consolidation: Reward filling tiny gaps
    if item_size < 28 && post_residual < 32 {
        score -= 710.0 * (1.0 + (item_size as f64 / 36.0));
    }

    // 9. High-Fill Reward: Non-linear penalty for sub-optimal packing
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill_ratio > 0.95 {
        score -= 1600.0 * fill_ratio.powi(12);
    }

    // 10. Anti-Fragmentation: Dynamic penalty for bins that drift above mean
    if mean_residual > bin_capacity as f64 * 0.25 {
        score += post_residual as f64 * 18.2;
    }

    score
}

