    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Predictive Lookahead: Refined slack-matching to prioritize deeper filling
    if next_item_size > 0 {
        if post_residual == 0 {
            score -= 585.0; 
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 490.0 / (1.0 + slack.powf(0.7) * 0.22);
        } else if !is_new_bin {
            score += 580.0 * (1.0 - progress).sqrt() * (1.0 + (open_bins_count as f64 * 0.32));
        }
    }

    // 2. Adaptive New-Bin Thresholding: Increased cost for new bin creation to force deeper compaction
    if is_new_bin {
        let utilization = 1.0 - (mean_residual / bin_capacity as f64);
        score += 750.0 + (utilization * 1050.0) + (progress * 600.0) + (open_bins_count as f64 * 12.0);
    } else if post_residual < (bin_capacity / 7) {
        score -= 720.0 * (1.0 - (post_residual as f64 / (bin_capacity as f64 / 7.0)).powi(2));
    }

    // 3. Residual Balancing: Tighten target drift to maintain consistency
    let residual_diff = post_residual as f64 - (mean_residual * 0.55);
    score += residual_diff.powi(2) * 0.55;

    // 4. Scarcity & Entropy: Stronger preference for existing bins when choices are limited
    if fitting_bins_count <= 4 && !is_new_bin {
        score -= 1250.0;
    }

    // 5. Temporal Compaction: Steeper penalty for late-game inefficiency
    if progress > 0.88 {
        score += (post_residual as f64).powf(1.4) * 350.0;
    } else {
        score -= (post_residual as f64) * 16.5;
    }

    // 6. Sliver Mitigation: Optimized for gaps that block large items
    if post_residual > 0 && post_residual <= 25 {
        score += 950.0 * (1.0 - (post_residual as f64 / 25.0)).powf(2.2);
    }

    // 7. Density Constraint: Tighten target residual
    let target_residual = bin_capacity as f64 * 0.02;
    score += (post_residual as f64 - target_residual).abs() * 19.5;

    // 8. Small Item Consolidation: Reward filling tiny gaps with flexible items
    if item_size < 20 && post_residual < 28 {
        score -= 820.0 * (1.0 + (item_size as f64 / 30.0));
    }

    // 9. High-Fill Reward: Aggressive bonus for near-perfect bin exhaustion
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill_ratio > 0.95 {
        score -= 1850.0 * fill_ratio.powi(14);
    }

    // 10. Anti-Fragmentation: Dynamic penalty for bins that drift above mean
    if mean_residual > bin_capacity as f64 * 0.20 {
        score += post_residual as f64 * 22.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: heavily penalize larger post_residuals.
    // We want the post_residual to be as close to 0 as possible.
    score += post_residual as f64 * 1.5;

    // 2. Harmonic Class Logic:
    // If post_residual is small, it creates a "fragment" that is likely unusable.
    // Penalize small fragments (e.g., 1-9) heavily as they are hard to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 / (post_residual as f64 + 0.1);
    }

    // 3. Lookahead Sensitivity:
    // If the next item exists, try to leave space for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
