    // If this is an empty bin (new bin candidate), only pick it if no other good options exist.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin unless we have very few open bins or 
        // the current options are all terrible.
        score += 35.0 + (open_bins_count as f64 * 2.0);
    }

    // 5. Density Balancing:
    // Prefer bins that are closer to the mean_residual to keep load balanced.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.2;

    // 6. Last Chance Logic:
    // If this is the only bin that fits the item, prioritize it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

