pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Predictive Lookahead: Refined to heavily prefer bins that leave space for the very next item
    if next_item_size > 0 {
        if post_residual == 0 {
            score -= 580.0; 
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 510.0 / (1.0 + slack.powf(0.65) * 0.15);
        } else if !is_new_bin {
            score += 620.0 * (1.0 - progress).sqrt() * (1.0 + (open_bins_count as f64 * 0.28));
        }
    }

    // 2. Adaptive New-Bin Thresholding: Increased cost of new bins to favor consolidation
    if is_new_bin {
        let utilization = 1.0 - (mean_residual / bin_capacity as f64);
        score += 750.0 + (utilization * 1050.0) + (progress * 580.0) + (open_bins_count as f64 * 12.0);
    } else if post_residual < (bin_capacity / 5) {
        score -= 680.0 * (1.0 - (post_residual as f64 / (bin_capacity as f64 / 5.0)).powi(2));
    }

    // 3. Residual Balancing: Tighter focus on balancing against mean residual to prevent "outlier" bins
    let residual_diff = post_residual as f64 - (mean_residual * 0.55);
    score += residual_diff.powi(2) * 0.55;

    // 4. Scarcity & Entropy: Stronger incentive to use bins when choices are limited
    if fitting_bins_count <= 4 && !is_new_bin {
        score -= 1150.0;
    }

    // 5. Temporal Compaction: Aggressive late-game closure
    if progress > 0.90 {
        score += (post_residual as f64).powf(1.4) * 350.0;
    } else {
        score -= (post_residual as f64) * 16.5;
    }

    // 6. Sliver Mitigation: Optimized for small gap filling
    if post_residual > 0 && post_residual <= 32 {
        score += 920.0 * (1.0 - (post_residual as f64 / 32.0)).powf(2.2);
    }

    // 7. Density Constraint: Target a tighter residual baseline
    let target_residual = bin_capacity as f64 * 0.03;
    score += (post_residual as f64 - target_residual).abs() * 19.5;

    // 8. Small Item Consolidation: High-reward for small items in tight gaps
    if item_size < 28 && post_residual < 35 {
        score -= 820.0 * (1.0 + (item_size as f64 / 40.0));
    }

    // 9. High-Fill Reward: Exponential reward for near-full bins
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill_ratio > 0.92 {
        score -= 1800.0 * fill_ratio.powi(14);
    }

    // 10. Anti-Fragmentation: Dynamic penalty for bins that exceed mean residual
    if mean_residual > bin_capacity as f64 * 0.20 {
        score += post_residual as f64 * 22.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space after placement. 
    // We want to minimize this (Best Fit principle).
    let mut score = post;

    // Penalize creating "fragmented" space (small, unusable residuals).
    // If post_residual is between 1 and 9, it's likely dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - (post / 10.0));
    }

    // Lookahead logic: if the next item fits into the current post_residual, 
    // prioritize this bin heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
    }

    // Dynamic pressure: As the stream nears the end, become more aggressive 
    // about filling existing bins to avoid leaving stragglers.
    let density_factor = (mean_residual / bin_capacity as f64) * 50.0;
    score += density_factor * progress;

    // If this is the only bin that fits, prioritize it to avoid opening a new bin
    // unless the fit is extremely poor (post_residual very small).
    if fitting_bins_count == 1 && post_residual < 5 {
        score += 30.0;
    }

    // Penalty for opening a new bin when other options exist.
    // The "new bin" candidate has bin_residual == bin_capacity.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 45.0 - (progress * 15.0);
    }

    // Non-linear coupling: penalize large residuals more heavily as the stream progresses
    // to force tighter packing in the final stages.
    score += (post.powf(1.5) / bin_capacity as f64) * progress;

    score
}

